module subsequence_string(\n    input [7:0] a, b, c, d,\n    output reg valid,\n    output reg [3:0] length,\n    output reg [15:0] string_bits\n);\n    // Allow lists\n    wire [8:0] n0_allowed;\n    wire [8:0] n1_allowed;\n\n    assign n0_allowed[0] = (a == 8'd0);\n    assign n0_allowed[1] = (a == 8'd0);\n    assign n0_allowed[2] = (a == 8'd1);\n    assign n0_allowed[3] = (a == 8'd3);\n    assign n0_allowed[4] = (a == 8'd6);\n    assign n0_allowed[5] = (a == 8'd10);\n    assign n0_allowed[6] = (a == 8'd15);\n    assign n0_allowed[7] = (a == 8'd21);\n    assign n0_allowed[8] = (a == 8'd28);\n\n    assign n1_allowed[0] = (d == 8'd0);\n    assign n1_allowed[1] = (d == 8'd0);\n    assign n1_allowed[2] = (d == 8'd1);\n    assign n1_allowed[3] = (d == 8'd3);\n    assign n1_allowed[4] = (d == 8'd6);\n    assign n1_allowed[5] = (d == 8'd10);\n    assign n1_allowed[6] = (d == 8'd15);\n    assign n1_allowed[7] = (d == 8'd21);\n    assign n1_allowed[8] = (d == 8'd28);\n\n    always @(*) begin\n        // Defaults\n        valid = 1'b0;\n        length = 4'd0;\n        string_bits = 16'b0;\n        \n        // Search variables\n        integer n0, n1;\n        integer p;\n        reg found = 1'b0;\n\n        for (n0 = 0; n0 <= 8 && !found; n0 = n0 + 1) begin\n            for (n1 = 0; n1 <= 8 && !found; n1 = n1 + 1) begin\n                if (n0_allowed[n0] && n1_allowed[n1] && (n0 + n1 > 0) &&\n                    ( (b + c) == (n0 * n1) )) begin\n                    found = 1'b1;\n                    valid = 1'b1;\n                    length = n0 + n1;\n                    \n                    // Prepare string\n                    if (n1 == 0) begin\n                        for (p = 0; p < n0; p = p + 1) begin\n                            string_bits[p] = 1'b0;\n                        end\n                    end else if (n0 == 0) begin\n                        for (p = 0; p < n1; p = p + 1) begin\n                            string_bits[p] = 1'b1;\n                        end\n                    end else begin\n                        reg [7:0] c_val = (n0 * n1) - b;\n                        integer q = c_val / n1;\n                        integer r = c_val % n1;\n                        reg [7:0] zeros_start = n0 - q - (r > 0 ? 1 : 0);\n                        \n                        for (p = 0; p < (n0 + n1); p = p + 1) begin\n                            if (p < zeros_start) begin\n                                string_bits[p] = 1'b0;\n                            end else if ((r > 0) && (p < (zeros_start + r))) begin\n                                string_bits[p] = 1'b1;\n                            end else if ((r > 0) && (p < (zeros_start + r + 1))) begin\n                                string_bits[p] = 1'b0;\n                            end else if (p < (zeros_start + r + (r > 0 ? 1 : 0) + (n1 - r))) begin\n                                string_bits[p] = 1'b1;\n                            end else begin\n                                string_bits[p] = 1'b0;\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end\nendmodule